var exit bool

func ato(s string) int {
	var n int
	first := true
	for i, _ := range s {
		if (s[0] == '-' || s[0] == '+') && first {
			first = false
			continue
		}
		if s[i] > '9' || s[i] < '0' {
			exit = true
		}
		n = n*10 + int(s[i]-'0')
	}
	if s[0] == '-' {
		return -n
	}
	return n
}

func main() {
	args := os.Args[1:]
	if len(args) != 2 {
		os.Stdout.WriteString("Usage: <program> <number> <width>\n")
		return

	}
	n := ato(args[0])
	for _, digit := range args[1] {
		if digit > '9' || digit < '0' {
			os.Stdout.WriteString("Incorrect width\n")
			return
		}
	}
	bi := ato(args[1])
	var r string
	if exit || n == 0 {
		for i := 1; i <= bi; i++ {
			os.Stdout.WriteString("0")
			if i%4 == 0 {
				os.Stdout.WriteString(" ")
			}
		}
		os.Stdout.WriteString("\n")
		return
	}
	sign := false
	if n < 0 {
		n = -n
		sign = true
	}
	for n > 0 {
		r = string(n%2+'0') + r
		n /= 2
	}
	// fmt.Println(r)
	for i := len(r); i < bi; i++ {
		r = "0" + r
	}
	if sign {
		sliceR := []rune(r)
		for i := 0; i < len(sliceR); i++ {
			if sliceR[i] == '0' {
				sliceR[i] = '1'
			} else {
				sliceR[i] = '0'
			}
		}
		for i := len(sliceR) - 1; i >= 0; i-- {
			if sliceR[i] == '1' {
				sliceR[i] = '0'
			} else {
				sliceR[i] = '1'
				break
			}
		}
		r = string(sliceR)
		if sliceR[0] == '0' {
			r = "1" + r
		}
	}
	for i := 0; i < len(r); i++ {
		os.Stdout.WriteString(string(r[i]))
		if (i-3)%4 == 0 {
			os.Stdout.WriteString(" ")
		}
	}
	os.Stdout.WriteString("\n")
}

