func hex(n int) string {
	base := "0123456789abcdef"
	sliceBase := []rune(base)
	index := []int{}
	var r []rune
	for n > 0 {
		index = append(index, n%16)
		n /= 16
	}
	for i := len(index) - 1; i >= 0; i-- {
		r = append(r, sliceBase[index[i]])
	}
	return string(r)
}

